import json

def final_transform(grid):
    h = len(grid)
    w = len(grid[0])
    output = [[0]*w for _ in range(h)]

    by_val = {}
    for r in range(h):
        for c in range(w):
            val = grid[r][c]
            if val != 0:
                by_val.setdefault(val, []).append((r, c))

    for val, cells in by_val.items():
        if not cells:
            continue

        rows = set(r for r, c in cells)
        cols = set(c for r, c in cells)
        min_r = min(rows)
        max_r = max(rows)
        min_c = min(cols)
        max_c = max(cols)

        # Vertical fill: for each column in cols, fill from the MIN r where this column has the value to the fill_end
        # fill_end is max_r if there are cells in multiple rows, else h-1 (bottom of grid)
        if len(rows) == 1:
            fill_end = h - 1  # Fill to bottom when there's only one row of cells
        else:
            fill_end = max_r

        for c in cols:
            r_start = min(r for r, cc in cells if cc == c)
            for r in range(r_start, fill_end + 1):
                if output[r][c] == 0:
                    output[r][c] = val

        # Horizontal fill at max_r if max_r > min_r (i.e., cells span multiple rows)
        if max_r > min_r:
            for c in range(min_c, max_c + 1):
                if output[max_r][c] == 0:
                    output[max_r][c] = val

    return output

