def solve_task_3b962c91(input_grid):
    """
    Solve task-3b962c91 by applying the transformation rule:
    - For each value, if all cells are in one row, fill that column to bottom
    - For values spanning multiple rows:
      - Fill vertically from each cell's row to max_row of that value
      - Fill horizontally at max_row between min_col and max_col
    """
    h = len(input_grid)
    w = len(input_grid[0]) if h > 0 else 0

    # Create output grid
    output = [[0]*w for _ in range(h)]

    # Collect all cells for each value
    by_val = {}
    for r in range(h):
        for c in range(w):
            val = input_grid[r][c]
            if val != 0 and val not in by_val:
                by_val[val] = []
            elif val != 0:
                by_val[val].append((r, c))

    # Sort cells by row, then column
    for val in by_val:
        by_val[val].sort()

    for val, cells in by_val.items():
        if not cells:
            continue

        # Get rows and cols for this value
        rows = set(r for r, c in cells)
        cols = set(c for r, c in cells)
        min_r = min(rows)
        max_r = max(rows)
        min_c = min(cols)
        max_c = max(cols)

        # Determine fill end for vertical fills
        if len(rows) == 1:
            fill_end = h - 1  # Fill to bottom when there's only one row of cells
        else:
            fill_end = max_r

        # Apply vertical fills: fill from cell's min_r to fill_end for each column
        for c in cols:
            r_start = min(r for r, cc in cells if cc == c)
            for r in range(r_start, fill_end + 1):
                if output[r][c] == 0:
                    output[r][c] = val

        # Apply horizontal fill at max_r (only if cells span multiple rows)
        if max_r > min_r:
            for c in range(min_c, max_c + 1):
                if output[max_r][c] == 0:
                    output[max_r][c] = val

    return output

